import{z as l,x as p,o as r,c as d,q as o,j as i,D as E,d as t,s,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"模糊检查点","description":"","frontmatter":{"title":"模糊检查点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fuzzy-checkpoint.md","filePath":"cs/fuzzy-checkpoint.md","lastUpdated":1791063341000}'),B={name:"cs/fuzzy-checkpoint.md"};function c(h,a,m,u,f,D){const n=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="模糊检查点" tabindex="-1">模糊检查点 <a class="header-anchor" href="#模糊检查点" aria-label="Permalink to &quot;模糊检查点&quot;">​</a></h1><div class="epigraph"><p>检查点不冻结世界：记下当时的脏页与活跃事务，后台继续刷；恢复用这份快照当分析起点，而不是要求检查点瞬间数据文件干净。</p><footer>—— 据 Mohan ARIES 检查点；Gray and Reuter；主干 checkpoint 课的模糊补全</footer></div><p><a href="/cs/aries-phases-clr">上一课</a>从检查点 LSN 开分析。本课不写 CLR。缺口是检查点本身：若采取 sharp（停更新、刷光脏页）则吞吐归零。模糊检查点（fuzzy checkpoint）允许检查点期间页继续变脏，只保证记录了「这些页可能脏、这些事务活跃」，redo 仍从足够早的 LSN 开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/checkpoint">检查点</a> 缩短恢复。模糊：写 begin-checkpoint，拷贝脏页表与事务表，写 end-checkpoint，再把检查点指针进控制文件。拷贝期间新脏页不在表里？规则是：拷贝后变脏的页，其 recoveryLSN 仍 ≥ 检查点，redo 从检查点前足够早处扫会覆盖。细节在 ARIES：脏页表含当时未刷页。</p><p>缺口是<strong>与刷脏并行</strong>：检查点不代替刷脏；后台写者降低 min recoveryLSN，使下次检查点更紧。两者一起决定 RTO。</p><p><span class="marginnote">模糊不是「随便丢日志」。WAL 仍先于页。检查点只限制崩溃后必须扫描的日志前缀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>周期或按日志体积触发。太频：写检查点记录与控制文件成为瓶颈。太稀：恢复扫太多。与组提交：检查点 LSN 之前的日志必须已持久。</p><p><span class="marginnote">直觉类比：sharp 检查点像商店打烊盘点——关门、清点、再开张；模糊检查点像「边营业边盘货」：先给账本拍张快照，之后照常做生意，快照只保证记下「当时哪些账可能还没结」。</span></p><p><span class="marginnote">术语翻译：RTO（Recovery Time Objective）是恢复时间目标——崩溃后允许多久恢复服务。检查点做得越勤、脏页刷得越紧，崩溃后要重放的日志就越短，RTO 就越小；代价是平时性能被摊薄。</span></p><p>复制：备库的 replay 位置类似检查点水位。备份常与检查点对齐拿一致点。</p>',12)),(r(),i(A,null,{default:E(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEG%5B%22begin%20checkpoint%22%5D%20--%3E%20SNAP%5B%22%E6%8B%B7%E8%B4%9D%E8%84%8F%E9%A1%B5%E8%A1%A8%20%2F%20%E4%BA%8B%E5%8A%A1%E8%A1%A8%22%5D%0A%20%20SNAP%20--%3E%20END%5B%22end%20checkpoint%22%5D%0A%20%20END%20--%3E%20CTL%5B%22%E6%8E%A7%E5%88%B6%E6%96%87%E4%BB%B6%E6%8C%87%E9%92%88%22%5D%0A%20%20BG%5B%22%E5%90%8E%E5%8F%B0%E5%88%B7%E8%84%8F%22%5D%20--%3E%20MIN%5B%22%E6%8E%A8%E8%BF%9B%20min%20recoveryLSN%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"恢复分析从最近完成的 end-checkpoint 走。半截检查点忽略，用上一个。与 TDE：检查点记录可含密钥版本。与缓冲 2Q：刷脏偏好老脏页，不是刚扫描的一次性页——策略与检查点目标对齐。",-1)),a[5]||(a[5]=e("p",null,"模糊检查点期间的崩溃：未完成检查点无效，正确性靠上一完成点+后续日志。",-1)),a[6]||(a[6]=e("p",null,"检查点写一半崩溃时恢复从哪里起步？答案是完全丢弃半成品、退回上一个完整检查点。",-1)),(r(),i(A,null,{default:E(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%E6%97%B6%E6%A3%80%E6%9F%A5%E7%82%B9%E5%8F%AA%E5%86%99%E4%BA%86%E4%B8%80%E5%8D%8A%22%5D%20--%3E%20HALF%5B%22begin%20%E6%9C%89%E3%80%81end%20%E6%B2%A1%E6%9C%89%22%5D%0A%20%20HALF%20--%3E%20INVALID%5B%22%E8%AF%A5%E6%A3%80%E6%9F%A5%E7%82%B9%E6%95%B4%E4%BD%93%E6%97%A0%E6%95%88%22%5D%0A%20%20INVALID%20--%3E%20PREV%5B%22%E5%9B%9E%E9%80%80%E7%94%A8%E4%B8%8A%E4%B8%80%E4%B8%AA%E5%AE%8C%E6%95%B4%E7%9A%84%20end-checkpoint%22%5D%0A%20%20PREV%20--%3E%20ANALYZE%5B%22%E6%8C%89%E5%AE%83%E7%9A%84%E8%84%8F%E9%A1%B5%E8%A1%A8%2F%E4%BA%8B%E5%8A%A1%E8%A1%A8%E5%BC%80%E5%A7%8B%E5%88%86%E6%9E%90%22%5D%0A%20%20ANALYZE%20--%3E%20REDO%5B%22redo%20%E4%BB%8E%E8%B6%B3%E5%A4%9F%E6%97%A9%E7%9A%84%20LSN%20%E5%90%91%E5%90%8E%E6%89%AB%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：若每 10 分钟做一次检查点，崩溃平均要重放约 10 分钟的日志；把周期缩到 1 分钟，重放量降到约 1 分钟，代价是每分钟多写一份快照并多刷一批脏页——恢复时间与运行开销就是这笔交换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比生理 vs 逻辑日志粒度。也不把检查点当 vacuum。RTO 课把时间预算量化。</p><p>后课默认：生产用模糊检查点+后台刷脏。日志粒度：记字节差、记操作、还是整页。</p><p>检查点是恢复的索引，不是把数据库变成只读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模糊检查点记录脏页与事务快照，不停机刷光。</li><li>后台刷脏推进 redo 起点；频率权衡恢复与运行。</li><li>日志粒度下一课。</li><li>出处：ARIES；Gray and Reuter；主干 checkpoint。</li></ul>',7))])}const S=l(B,[["render",c]]);export{N as __pageData,S as default};
